'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const main=$('#main');let motionPaused=matchMedia('(prefers-reduced-motion: reduce)').matches, scene=null, revealObserver=null, pageAnimations=[], manualScene=false, spriteObserver=null, spriteTick=0;
const sprite=(name,cls='',label='')=>ASSETS[name]?`<span class="sprite ${cls}" data-sprite="${name}" ${label?`role="img" aria-label="${label}"`:'aria-hidden="true"'} style="background-image:url('${ASSETS[name]}')"></span>`:'';
const cloud=(name,cls)=>`<span class="hero-cloud ${cls}" aria-hidden="true" style="background-image:url('${ASSETS[name]}')"></span>`;
const still=(name,cls='')=>ASSETS[name]?`<span class="sprite ${cls}" aria-hidden="true" style="background-image:url('${ASSETS[name]}')"></span>`:'';
const img=(name,alt,cls='')=>`<img src="${ASSETS[name]}" alt="${alt}" class="${cls}" decoding="async">`;
const link=(text,path,cls='pill')=>`<a href="#${path}" class="${cls}">${text}</a>`;
const eyebrow=t=>`<span class="eyebrow">${t}</span>`;
const actions=(...a)=>`<div class="actions">${a.join('')}</div>`;
const crumbs=(label,path='/')=>`<div class="breadcrumb"><a href="#/">Home</a><span>/</span>${path!=='/'?`<a href="#${path}">${path.startsWith('/motors')?'Motor Systems':'Drone Solutions'}</a><span>/</span>`:''}<span>${label}</span></div>`;
const hero=(label,title,desc,asset,cta='Start a conversation',url='/contact',portal='/')=>`<section class="page-hero"><div class="wrap">${crumbs(label,portal)}<div class="split"><div>${eyebrow(label)}<h1>${title}</h1><p>${desc}</p>${actions(link(cta,url))}</div>${img(asset,asset.startsWith('company-')?'FORKLS at an industry event':label+' — engineering illustration',asset.startsWith('company-')?'photo reveal':'art reveal')}</div></div></section>`;
const simple=(label,title,desc,cta='',path='')=>`<section class="page-hero simple">${crumbs(label)}${eyebrow(label)}<h1>${title}</h1><p>${desc}</p>${cta?actions(link(cta,path)):''}</section>`;
const section=(html,cls='')=>`<section class="section ${cls}"><div class="wrap">${html}</div></section>`;
const cta=(title='Your next idea.<br><em>Let’s make it fly.</em>',desc='Tell us where you want to go. We’ll help you work through the engineering that gets you there.',btn='Start a conversation',url='/contact')=>`<section class="cta"><div class="wrap cta-inner">${still('journey-balloon-sprite','cta-balloon')}<div>${eyebrow('Possibility begins with a conversation')}<h2>${title}</h2><p>${desc}</p>${actions(link(btn,url))}</div></div></section>`;
const card=(title,desc,path,asset='',num='')=>`<a class="card ${asset?'artcard':''} reveal" href="#${path}">${asset?img(asset,title):''}<div>${num?`<span class="num">${num}</span>`:''}<h3>${title}</h3><p>${desc}</p><span class="textlink">Explore ${title.toLowerCase()}</span></div></a>`;
const values=(items)=>`<div class="values">${items.map(([t,d],i)=>`<article class="value reveal"><span class="num">0${i+1}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div>`;
const table=rows=>`<table class="specs"><tbody>${rows.map(([a,b])=>`<tr><th scope="row">${a}</th><td>${b}</td></tr>`).join('')}</tbody></table>`;
const faq=items=>`<div class="faq">${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
const featureRows=items=>items.map(([t,d],i)=>`<article class="feature-row reveal"><span class="num">0${i+1}</span><h3>${t}</h3><p>${d}</p></article>`).join('');
function explode(){
 const labels=[['Propellers','Lift starts here'],['Motor & airframe','Structure meets motion'],['Protective shell','Built around the mission'],['Flight electronics','Control & connection'],['Battery module','Energy for the journey'],['Landing gear & payload','A purpose in every part']];
 return `<section class="explode-section" aria-label="Interactive exploded drone illustration"><div class="explode-sticky"><div class="explode-title">${eyebrow('A closer look at what makes it fly')}<h2>Every part.<br>A part of the <em>possibility.</em></h2><p>Scroll to explore the systems, or use the controls below.</p></div><div class="explode-stage" role="img" aria-label="A drone separates into propellers, motor and airframe, protective shell, flight electronics, battery, and landing gear with payload.">${labels.map(([title,detail],i)=>`<figure class="part-slot slot${i}"><div class="part-picture"><div class="drone-layer layer${i}" style="background-image:url('${ASSETS['drone-components-sheet']}')"></div></div><figcaption class="partlabel"><small>0${i+1} / ${detail}</small><b>${title}</b></figcaption></figure>`).join('')}</div><div class="explode-controls"><label for="drone-range">Assemble <input id="drone-range" type="range" min="0" max="100" value="0" aria-label="Drone assembly separation"> Explore</label><button class="pill small plain" id="explode-button">Explore the parts</button></div><p class="explode-caption">Illustrative system architecture. Components vary by platform; this is not a production assembly drawing.</p></div></section>`;
}
function home(){return `<section class="hero"><div class="hero-content">${eyebrow('Canadian engineering. From idea to possibility.')}<h1>Great ideas deserve<br>to <em>take flight.</em></h1><p class="hero-copy">Precision motor systems. Purpose-built drone solutions.<br>One team to help you find your way forward.</p><div class="actions"><div class="hero-choice">${link('Motor Systems <span aria-hidden="true">→</span>','/motors')}<small>For builders & innovators</small></div><div class="hero-choice">${link('Drone Solutions <span aria-hidden="true">→</span>','/drones','pill gold')}<small>For missions that matter</small></div></div></div><div class="hero-scene">${img('hero-ink-landscape','An ink illustration of a winding Canadian river, open prairie and pine trees','landscape')}${cloud('hero-cloud-a','cloud-a')}${cloud('hero-cloud-b','cloud-b')}${cloud('hero-cloud-c','cloud-c')}<span class="hero-drift">${sprite('journey-balloon-sprite','hero-balloon')}</span></div></section><div class="intro-band"><div class="wrap"><p>Small details. <em>Extraordinary possibilities.</em></p><span>Edmonton, Alberta · Canada</span></div></div>
<section class="story-section" id="home-story"><div class="wrap"><div class="story-paper">${sprite('sketch-compass-sprite','story-compass')}<div class="center"><h2>Good ideas need<br>a little <em>direction.</em></h2></div><div class="story-columns"><div><p>A motor is part of a system. A drone is part of a mission. And every useful solution begins with understanding what you want to achieve.</p><p>FORKLS brings propulsion engineering, manufacturing and drone development together. From your first question to the details of an integration, we help connect the decisions that move your project forward.</p><p class="story-signoff">The FORKLS team</p>${link('Get to know us <span aria-hidden="true">→</span>','/company','textlink')}</div><figure>${img('company-conversation','A FORKLS representative at the company’s industry-event display','photo')}<figcaption>FORKLS, out in the engineering community.</figcaption></figure></div></div></div></section>
<section class="pathways section"><div class="wrap"><div class="intro-copy center">${eyebrow('One company. Two paths.')}<h2>More power.<br>A little more <em>perspective.</em></h2><p>Start with the component you’re developing or the work you need to do.<br>Both paths lead to the same hands-on engineering team.</p></div><div class="service-row"><div class="service-art motor-art">${img('bldc-motor-cutaway','An illustrated brushless motor with copper windings and a precision airframe','art')}${sprite('maple-breeze-sprite','service-leaf')}</div><div>${eyebrow('01 / Motor systems')}<h3>At the heart of<br><em>what you build.</em></h3><p>Brushless motors, matched propulsion, custom engineering and manufacturing. Build from a motor family, or begin with a requirement that needs its own solution.</p>${link('Explore motor systems <span aria-hidden="true">→</span>','/motors')}</div></div><div class="path-connector" aria-hidden="true"></div><div class="service-row reverse"><div class="service-art">${img('agriculture-mission','An ink illustration of a drone mission over Canadian farmland','art')}</div><div>${eyebrow('02 / Drone solutions')}<h3>A clearer view.<br>A <em>purposeful mission.</em></h3><p>Platforms and development built around the job. Explore agriculture, mapping, inspection and research, with parts and support for the journey ahead.</p>${link('Explore drone solutions <span aria-hidden="true">→</span>','/drones')}</div></div></div></section>
${explode()}
${journal(false)}
<section class="community-section"><div class="wrap community-grid"><article><span class="editorial-label">Support along the way</span>${sprite('sketch-compass-sprite','community-art')}<h2>A little help.<br>When you <em>need it.</em></h2><p>Find technical resources, prepare a parts enquiry, or talk through a training need with the team.</p>${link('Find support <span aria-hidden="true">→</span>','/drones/support')}</article><article><span class="editorial-label">People & purpose</span>${img('company-gathering','People meeting at a FORKLS-supported industry gathering','community-photo')}<h2>Good conversations.<br><em>New possibilities.</em></h2><p>Engineering begins with people. Meet the company behind the components and the conversations behind the work.</p>${link('Meet FORKLS <span aria-hidden="true">→</span>','/company')}</article></div></section>
${questionSection()}
${cta('An idea worth exploring.<br>A path <em>worth taking.</em>','Start with your question. We’ll help you find the next useful step.','Let’s talk <span aria-hidden="true">→</span>')}`;}
function journal(full=false){return `<section class="journal section" id="home-news"><div class="wrap"><div class="journal-rule"><span>From the workshop</span><i></i><span class="journal-wordmark">FORKLS</span><i></i><span>Ideas in motion</span></div><div class="journal-heading"><span>News &<br><em>notes</em></span><${full?'h1':'h2'}>INSIGHTS</${full?'h1':'h2'}><span>Made in<br><em>Canada</em></span></div><p class="journal-deck">Company news, engineering perspectives, and the people behind the work.</p><div class="journal-topics"><span>Motor systems</span><span>Drone development</span><span>Engineering</span><span>Company stories</span></div><div class="journal-grid"><a class="journal-lead" href="#/news/xrotor-production"><figure class="journal-image illustration">${img('bldc-motor-cutaway','Illustrative cutaway of a brushless motor with copper windings')}</figure><div class="article-meta"><span>Product news</span><time datetime="2026-09-07">7 Sep 2026</time></div><h3>XRotor 2800.<br>A new chapter in production.</h3><p>FORKLS announces its high-volume production line for the XRotor 2800 brushless motor series.</p><span class="textlink">Read the story <span aria-hidden="true">→</span></span></a><div class="journal-side"><a href="#/news/field-notes"><figure class="journal-image">${img('company-event','FORKLS at an industry exhibition')}</figure><div class="article-meta"><span>Company</span><span>Field notes</span></div><h3>Where ideas meet.<br>FORKLS in the community.</h3></a><a href="#/news/engineering-notes"><figure class="journal-image blueprint">${img('blueprint','FORKLS motor engineering drawing')}</figure><div class="article-meta"><span>Engineering guide</span><span>Propulsion</span></div><h3>Start with the mission.<br>Then choose the motor.</h3></a></div></div>${full?'':`<div class="journal-bottom"><i></i>${link('View all news <span aria-hidden="true">→</span>','/news','pill small')}<i></i></div>`}</div></section>`;}
function questionSection(){return `<section class="question-section section"><div class="wrap"><div class="center">${eyebrow('The FORKLS question jar')}<h2>What’s on<br><em>your drawing board?</em></h2><p>A question is a good place to begin.</p></div><div class="question-grid"><div><form class="brief-form question-form" data-brief="Project question">${field('Full name','Name','text','Your name',true)}${field('Email','Email','email','you@company.com',true)}${select('I’m interested in','Enquiry',['Motor Systems','Drone Solutions','Custom engineering','Parts & support','Other'],true)}${textarea('Your question','Question','Tell us what you’re working on.',true)}${formFooter()}</form><div class="result" hidden role="status"></div></div><div class="question-illustration">${sprite('inquiry-hand-sprite','question-jar','An ink-drawn hand placing a question card into a mint glass jar')}</div></div></div></section>`;}
const productFamilies=[
 {id:'micro',name:'Micro & Compact',use:'Precision in a smaller footprint.',desc:'Compact brushless motors for size-sensitive airframes, robotics and small propulsion systems.',category:'Compact',rows:[['Design focus','Low-mass, space-conscious integration'],['Applications','Compact aerial platforms and robotics'],['Configuration','Winding, shaft and mounting requirements by project'],['Performance','Request validated data for the selected motor']]},
 {id:'mid-size',name:'Mid-size Systems',use:'Balance, beautifully engineered.',desc:'Propulsion development that balances thrust, thermal behaviour and integration for working aerial platforms.',category:'Mid-size',rows:[['Design focus','Thrust, efficiency and thermal balance'],['Applications','Multirotor and mission-specific UAV systems'],['Integration','Motor, controller and propeller matching'],['Performance','Depends on selected motor and operating point']]},
 {id:'heavy-lift',name:'Heavy-lift Systems',use:'More ambition. More capability.',desc:'Large-format propulsion development for demanding payloads and industrial aircraft programmes.',category:'Heavy-lift',rows:[['Development focus','Large-format BLDC propulsion'],['Design programme','155–167 mm class; confirm the current configuration'],['Integration','Motor, ESC, propeller and cooling considered together'],['Status','Engineering review and configuration confirmation required']]},
 {id:'fixed-wing',name:'Fixed-wing & VTOL',use:'From lift to the long view.',desc:'Propulsion engineering for forward flight, transition and integrated lift architectures.',category:'VTOL',rows:[['Applications','Fixed-wing and vertical take-off aircraft'],['Design considerations','Cruise duty, take-off demands and transitions'],['Interfaces','Mounting, controls and electrical system by project'],['Validation','Programme-specific testing and acceptance criteria']]},
 {id:'xrotor-2800',name:'XRotor 2800',use:'A compact platform. Room to explore.',desc:'Explore FORKLS’ XRotor 2800 BLDC motor family, including 2807 and 2812 configurations.',category:'Compact',rows:[['Product type','Brushless DC motor'],['Configurations','2807 and 2812'],['2807','Compact stator configuration'],['2812','Taller stator configuration for torque-focused applications'],['KV, weight & thrust','Confirm current specification and validated performance data']]}
];
function motors(){return hero('Motor Systems','Every great journey<br>starts with <em>motion.</em>','From compact brushless motors to custom propulsion programmes. Engineering for the builders turning ambitious ideas into working machines.','bldc-motor-cutaway','Explore our motors','/motors/products')+section(`<div class="sectiontop"><div>${eyebrow('The heart of what you build')}<h2>Find your<br><em>starting point.</em></h2></div><p>Begin with a motor family. Then refine the winding, interfaces and system around your requirements.</p></div><div class="grid4">${productFamilies.slice(0,4).map((p,i)=>card(p.name,p.desc,'/motors/products/'+p.id,'','0'+(i+1))).join('')}</div>`)+section(`<div class="split">${img('blueprint','FORKLS motor engineering blueprint','art reveal')}<div>${eyebrow('From requirement to repeatability')}<h2>Your challenge.<br>Our <em>drawing board.</em></h2><p>Sometimes the right motor does not exist yet. We work through electromagnetic design, thermal behaviour, winding, machining and validation to make the next step clear.</p>${actions(link('Explore custom engineering','/motors/custom'))}</div></div>`,'tinted')+section(values([['Systems, not isolated parts','Match the motor, controller and propeller to the job they need to do together.'],['Testing with a purpose','Agree on operating points and acceptance criteria before drawing conclusions.'],['A path to production','Consider materials, process and procurement as part of the engineering from day one.']]))+cta('Let’s give your idea<br><em>some momentum.</em>','Tell us your voltage, propeller, duty cycle and development goals.','Talk motor systems','/contact?type=Motor%20Systems');}
function products(){return simple('Motors & propulsion','A little precision.<br>A lot of <em>possibility.</em>','Explore motor families and begin a conversation about the operating point your project needs.')+section(`<div class="filterbar" aria-label="Filter motor families">${['All','Compact','Mid-size','Heavy-lift','VTOL'].map((t,i)=>`<button data-filter="${t}" aria-pressed="${i===0}">${t}</button>`).join('')}</div><div class="grid3 products">${productFamilies.map(p=>`<article class="card reveal" data-category="${p.category}">${img('bldc-motor-cutaway','Illustrative motor cutaway')}<span class="tag">${p.category}</span><h3>${p.name}</h3><p>${p.desc}</p>${link('Explore the family','/motors/products/'+p.id,'textlink')}</article>`).join('')}</div><p class="note" style="margin-top:25px">Illustrations show engineering concepts. Final dimensions, ratings, availability and test data must be confirmed for your chosen configuration.</p>`)+cta('Can’t find the right fit?<br><em>Let’s create it.</em>','Start with your requirements. We’ll help shape a development brief.','Custom engineering','/motors/custom');}
function product(p){return hero(p.name,p.use.replace('.','.<br>'),p.desc,'bldc-motor-cutaway','Discuss this motor','/contact?type='+encodeURIComponent(p.name),'/motors')+section(`<div class="split"><div>${eyebrow('At a glance')}<h2>Details make<br>the <em>difference.</em></h2><p>Start here, then request the drawing and performance information that match your revision and operating conditions.</p></div>${table(p.rows)}</div>`)+section(`<div class="grid3">${card('Performance data','Request thrust, torque, efficiency and thermal results with the propeller, voltage and test conditions clearly identified.','/contact?type=Performance%20data')}${card('Integration drawings','Request current dimensions, mounting interfaces and STEP availability for the exact configuration.','/motors/resources')}${card('Matched propulsion','Discuss controller, propeller, power supply, cooling and operating limits as one system.','/motors/custom')}</div>`,'tinted')+section(faq([['Can I compare 2807 and 2812 configurations?','For XRotor 2800, the two configurations use different stator heights. Ask FORKLS for current drawings and test results at the same operating point before selecting one.'],['Where are the performance curves?','Configuration-specific curves and published test reports are requested through the engineering team. Ask for tested curves for your selected revision.'],['Can the motor be customised?','Use the project brief to describe voltage, available space, target thrust or torque, duty cycle, thermal environment and annual quantity. FORKLS can review the engineering requirements.']]))+cta();}
function custom(){return hero('Custom engineering','What if<br>became <em>what’s next?</em>','A different airframe. A difficult operating point. An idea that needs its own solution. Start with the requirement, and build the system around it.','blueprint','Start an engineering brief','/contact?type=Custom%20engineering','/motors')+section(featureRows([['Define the real requirement','Payload, thrust or torque, electrical supply, space, duty cycle, temperature and service conditions define the problem.'],['Design the system','Explore electromagnetic geometry, winding, materials, thermal paths and motor-controller-propeller integration.'],['Prototype with purpose','Develop parts and assemblies that answer the questions with the greatest effect on the programme.'],['Measure, learn, refine','Use agreed test conditions and documented results to guide the next engineering decision.'],['Prepare for repeatability','Review drawings, process controls, sourcing, inspection and procurement needs before scaling.']]))+cta('Bring us your<br><em>interesting problem.</em>','A few well-chosen requirements are enough to begin.','Prepare a project brief','/contact?type=Custom%20engineering');}
function manufacturing(){return hero('Manufacturing','Good engineering.<br><em>Made repeatable.</em>','Development and production need to speak the same language. Build a procurement conversation around drawings, materials, quantities and verification.','blueprint','Discuss manufacturing','/contact?type=Manufacturing','/motors')+section(values([['Design for manufacture','Review tolerances, materials, machining, winding and assembly early in the programme.'],['Quality you can specify','Define inspection points, acceptance criteria, revision control and the records your programme requires.'],['Supply that fits your plan','Share annual demand, batch quantities, forecast, delivery milestones and any sourcing constraints.']]))+section(`<div class="split"><div>${eyebrow('Ready for a useful quotation')}<h2>Start with<br>the <em>right details.</em></h2><p>Lead time, minimum quantity and commercial terms depend on configuration and programme scope. Request a quotation for your current revision.</p></div>${table([['Technical package','Drawings, interfaces and controlled revision'],['Demand','Prototype count, order quantity and annual forecast'],['Delivery','Required dates and programme milestones'],['Verification','Inspection, tests and acceptance criteria'],['Sourcing','Material origin and procurement requirements']])}</div>`,'tinted')+cta();}
const industries=[['Aerospace & UAV','Propulsion development for multirotor, fixed-wing and VTOL architectures.'],['Robotics & autonomy','Compact motion systems designed around mechanical and electrical integration.'],['Industrial systems','Motor development for demanding duty cycles, environments and repeatable operation.'],['Research & development','Prototyping and test programmes that turn a technical question into a measurable result.']];
function motorIndustries(){return simple('Industries','Different challenges.<br>The same <em>curiosity.</em>','Start with the application. Work backwards to the motor, interfaces and validation your system needs.')+section(`<div class="grid2">${industries.map(([t,d],i)=>card(t,d,'/contact?type='+encodeURIComponent(t),'','0'+(i+1))).join('')}</div>`)+cta();}
function testSvg(){return img('bldc-motor-cutaway','Illustrative brushless motor cutaway','test-motor');}
function testing(){return hero('Test & validation','Less guesswork.<br>More <em>understanding.</em>','Good results start with a clear question, a repeatable setup and the right conditions. Define what success looks like before the test begins.','blueprint','Request test information','/contact?type=Test%20data','/motors')+section(`<div class="split"><div>${eyebrow('From the bench to the big picture')}<h2>See the system<br>in <em>motion.</em></h2><p>Thrust, torque, current, efficiency and temperature tell different parts of the story. Read them together, at the actual operating point.</p><p class="note">Request configuration-specific results and the conditions under which they were measured.</p></div><div class="teststand">${testSvg()}<p class="note">Motor illustration · request measured data for your selected configuration</p></div></div>`)+section(values([['Conditions matter','Record voltage, controller settings, propeller, ambient conditions and mounting.'],['Look across the envelope','Consider start-up, steady-state loads, transient demand and thermal limits.'],['Keep the evidence useful','Request the report for the exact configuration and revision you plan to integrate.']]),'tinted')+cta('Ask a better question.<br>Get a <em>more useful result.</em>','Share your configuration and the data you need for your next design decision.','Request a test report','/contact?type=Test%20report');}
function resources(drone=false){const rows=drone?[['Mission planning checklist','Define the task, site and operating constraints.','/drones/configure'],['Platform configuration review','Plan payload, sensors, communications and power.','/drones/platforms'],['Maintenance & repair guidance','Start with the model, serial and reported issue.','/drones/support'],['Parts identification','Prepare a parts enquiry with the right identifiers.','/drones/parts'],['Field stories','See authentic moments from FORKLS’ community.','/news/field-notes']]:[['Datasheets & performance reports','Request the current revision','/contact?type=Datasheet%20request'],['CAD / STEP & interface drawings','Ask about the selected configuration','/contact?type=CAD%20request'],['Integration & operating guidance','Discuss your motor, controller and propeller','/contact?type=Integration%20guidance'],['Custom development checklist','Build an engineering brief','/contact?type=Custom%20engineering'],['Testing & validation','Understand the test context','/motors/testing']];return simple(drone?'Field resources':'Technical resources',drone?'A little preparation.<br>A better <em>mission.</em>':'The details behind<br>your next <em>decision.</em>',drone?'Practical starting points for operators, development teams and procurement.':'Request configuration-specific documentation from the FORKLS team. Drawings, reports and availability must match the product revision.')+section(`<div class="resources-list">${rows.map(([t,d,p])=>`<a href="#${p}"><strong>${t}</strong><small>${d}</small></a>`).join('')}</div>`)+cta();}
const applications=[{id:'agriculture',name:'Agriculture',desc:'Bring aerial perspective to crop monitoring and field operations.',asset:'agriculture-mission',mission:'Define acreage, field access, crop conditions and the desired operation. Payload and operating approval determine the appropriate platform.',steps:['What needs to be measured or applied?','What area and turnaround must the mission cover?','What payload, handling and training does the operation require?']},{id:'mapping',name:'Mapping & surveying',desc:'Plan repeatable data capture for land, infrastructure and change over time.',asset:'mapping-mission',mission:'Work back from the required deliverable, coverage and accuracy. Sensor, positioning, flight planning and processing belong in the same discussion.',steps:['What deliverable and accuracy are required?','What terrain, area and access constraints apply?','Which sensor, positioning and processing workflow will be used?']},{id:'inspection',name:'Infrastructure inspection',desc:'Get a closer view of assets that are difficult to reach.',asset:'mapping-mission',mission:'Define the asset, stand-off distance, sensor requirements and reporting output before choosing the aircraft.',steps:['What defects or conditions must be identified?','What proximity, access and site risks shape the mission?','What imagery and reporting does the asset owner need?']},{id:'public-safety',name:'Public safety',desc:'Build situational awareness around the people and procedures on the ground.',asset:'company-conversation',mission:'Plan a mission around operational responsibility, information handling, communications and the environment. Platform suitability requires a configuration review.',steps:['Who operates the system and receives the information?','What sensor, communications and endurance are required?','What procurement, information handling and training rules apply?']},{id:'research',name:'Research & development',desc:'A flexible starting point for the questions that come next.',asset:'blueprint',mission:'Start with the experiment. Define interfaces, payload needs, data collection and repeatability before setting the development scope.',steps:['What question must the prototype answer?','What payload, interfaces and data are required?','How will the result be verified and repeated?']}];
function drones(){return hero('Drone Solutions','A bigger view.<br>A new <em>perspective.</em>','For the people turning aerial technology into useful work. Explore platforms, develop your mission, and keep the right parts and support close at hand.','mapping-mission','Find your mission','/drones/applications')+section(`<div class="sectiontop"><div>${eyebrow('Built around the work you do')}<h2>What’s on<br>your <em>horizon?</em></h2></div><p>There’s no one-size-fits-all mission. Start with the job and work towards the right system.</p></div><div class="grid3">${applications.slice(0,3).map(p=>card(p.name,p.desc,'/drones/applications/'+p.id,p.asset)).join('')}</div>`)+explode()+section(`<div class="split">${img('company-conversation','Illustrated technician servicing a drone','art reveal')}<div>${eyebrow('The flight is only part of the story')}<h2>Support for<br>the <em>whole journey.</em></h2><p>Identify the right spare, describe a repair or build a training request. A useful conversation starts with your platform, configuration and the work ahead.</p>${actions(link('Parts & spares','/drones/parts'),link('Support & training','/drones/support','pill plain'))}</div></div>`)+cta('A mission in mind?<br><em>Let’s map it out.</em>','Create a mission brief to discuss configuration and suitability with FORKLS.','Build your mission','/drones/configure');}
