function company(){return hero('Our company','Curious minds.<br><em>Things that move.</em>','FORKLS connects motor engineering, manufacturing and drone development from Edmonton, Alberta. One team, with a shared interest in turning possibility into practical motion.','company-conversation','Why FORKLS','/why-forkls')+section(`<div class="intro-copy center">${eyebrow('From first principles to the first flight')}<h2 class="reveal">The best ideas begin with a question.<br><em>What if we could make this better?</em></h2><p>A motor is never just a motor. It belongs to a system, a machine and a mission. Understanding that context helps us make better decisions about what comes next.</p></div>`)+section(values([['Engineering with context','Connect the component to its electrical, thermal and mechanical environment.'],['Development with purpose','Use prototypes and tests to answer the questions that matter to the programme.'],['Relationships that build','Work from clear requirements, practical conversations and shared next steps.']]),'tinted')+cta();}
