const routes={'/':home,'/motors':motors,'/motors/products':products,'/motors/custom':custom,'/motors/manufacturing':manufacturing,'/motors/industries':motorIndustries,'/motors/testing':testing,'/motors/resources':()=>resources(false),'/drones':drones,'/drones/platforms':platforms,'/drones/platforms/agriculture':()=>platform(false),'/drones/platforms/vtol':()=>platform(true),'/drones/applications':applicationList,'/drones/configure':configure,'/drones/parts':parts,'/drones/support':support,'/drones/resources':()=>resources(true),'/drones/public-sector':publicSector,'/company':company,'/why-forkls':why,'/news':news,'/news/field-notes':fieldNotes,'/news/xrotor-production':productionNews,'/news/engineering-notes':engineeringNotes,'/contact':contact,'/careers':careers,'/account':account,'/privacy':privacy,'/credits':credits};
