function hydrate(root=document){$$('[data-asset]',root).forEach(e=>{e.src=ASSETS[e.dataset.asset];});$$('[data-sprite]',root).forEach(e=>{if(ASSETS[e.dataset.sprite])e.style.backgroundImage="url('"+ASSETS[e.dataset.sprite]+"')";});}
function closeNav(){ $$('.dropdown.open').forEach(x=>x.classList.remove('open'));$$('.nav-trigger').forEach(x=>x.setAttribute('aria-expanded','false'));$('.nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Open navigation');document.body.classList.remove('menu-open'); }
function render(){pageAnimations.forEach(a=>a.pause());pageAnimations=[];if(spriteObserver)spriteObserver.disconnect();cancelAnimationFrame(spriteTick);if(scene)scene.pause();scene=null;if(revealObserver)revealObserver.disconnect();manualScene=false;document.body.classList.remove('scene-in-view');closeNav();const full=location.hash.slice(1)||'/',[path,query]=full.split('?');document.body.classList.toggle('drone-theme',path.startsWith('/drones'));main.innerHTML=(routes[path]||notFound)();hydrate(main);window.scrollTo({top:0,behavior:'instant'});const title=$('h1',main)?.innerText.replace(/\n/g,' ').replace(/\s+/g,' ').trim()||'FORKLS';document.title=path==='/'?'FORKLS — Great ideas deserve to take flight':title+' — FORKLS';const q=new URLSearchParams(query||'');if(q.has('type')&&$('.brief-form')){const type=q.get('type'),sel=$('select[name="Enquiry"]');if(sel){let opt=[...sel.options].find(o=>o.value===type);if(!opt){opt=new Option(type,type);sel.add(opt);}sel.value=type;}}setupForms();setupScene();setupReveal();setupSprites();if(!motionPaused&&$('.hero-content'))pageAnimations.push(anime({targets:$$('.hero-content > *'),opacity:[0,1],translateY:[8,0],delay:anime.stagger(65),duration:600,easing:'easeOutCubic'}));$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$$('[data-category]').forEach(x=>{x.hidden=b.dataset.filter!=='All'&&x.dataset.category!==b.dataset.filter;});}));}
function setupReveal(){if(motionPaused)return;revealObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){pageAnimations.push(anime({targets:e.target,opacity:[.7,1],translateY:[8,0],duration:550,easing:'easeOutCubic'}));revealObserver.unobserve(e.target);}});},{threshold:.08});$$('.reveal',main).forEach(e=>revealObserver.observe(e));}
function setupSprites(){
 const sprites=$$('[data-sprite]');if(!sprites.length||motionPaused)return;
 const visible=new Set(),starts=new WeakMap();
 spriteObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){visible.add(e.target);starts.set(e.target,performance.now());}else visible.delete(e.target);});},{rootMargin:'25px',threshold:.1});
 sprites.forEach(e=>spriteObserver.observe(e));
 const tick=now=>{if(motionPaused)return;if(!document.hidden)visible.forEach(e=>{
  const hand=e.dataset.sprite.includes('hand'),compass=e.dataset.sprite.includes('compass');
  const step=hand?180:compass?170:160;
  const frame=Math.min(11,Math.floor(((now-(starts.get(e)||now))%(step*12))/step));
  if(e.dataset.frame!==String(frame)){e.dataset.frame=frame;e.style.backgroundPosition=`${frame%4*100/3}% ${Math.floor(frame/4)*50}%`;}
 });spriteTick=requestAnimationFrame(tick);};spriteTick=requestAnimationFrame(tick);
}
function setupScene(){
 const section=$('.explode-section');if(!section)return;
 const stage=$('.explode-stage'),range=$('#drone-range'),button=$('#explode-button');
 const previous=+range.value||0;
 if(scene)scene.pause();
 // Remove previous transforms before measuring the responsive grid's final positions.
 const layers=$$('.drone-layer',stage);layers.forEach(el=>{el.style.transform='none'});
 const stageBox=stage.getBoundingClientRect(),wide=stage.clientWidth>700;
 const assembly=Math.min(stage.clientWidth*.78,wide?355:280);
 // The six cells are drawn in register as one composite drone, so the assembled state has to
 // stack them at an identical centre and an identical size. A per-layer scale or offset shears
 // the drone apart instead of assembling it: layer0/1 would render at 1.00 of the assembled box
 // while layer3 renders at 0.41 of it. Keep both arrays index-coupled to the six layers, uniform.
 const ratios=[1,1,1,1,1,1],offsets=[0,0,0,0,0,0];
 scene=anime.timeline({autoplay:false,easing:'easeInOutCubic'});
 layers.forEach((el,i)=>{
  const target=el.getBoundingClientRect();
  const startX=stageBox.left+stageBox.width/2-(target.left+target.width/2);
  const startY=stageBox.top+stageBox.height*.48+assembly*offsets[i]-(target.top+target.height/2);
  scene.add({targets:el,translateX:[startX,0],translateY:[startY,0],rotate:[-3,0],scale:[assembly*ratios[i]/Math.max(target.width,1),1],duration:1000},0);
 });
 scene.add({targets:$$('.partlabel',stage),opacity:[0,1],duration:200,easing:'linear'},800);
 const seek=v=>{const value=Math.max(0,Math.min(100,v));scene.seek(value*10);range.value=Math.round(value);button.textContent=value>50?'Reassemble drone':'Explore the parts';};
 range.oninput=()=>{manualScene=true;seek(+range.value)};
 button.onclick=()=>{manualScene=true;const state={v:+range.value},target=state.v>50?0:100;if(motionPaused){seek(target);return;}pageAnimations.push(anime({targets:state,v:target,duration:1100,easing:'easeInOutCubic',update:()=>seek(state.v)}));};
 scene.updateFromScroll=()=>{
  const box=section.getBoundingClientRect();
  document.body.classList.toggle('scene-in-view',box.top<innerHeight*.45&&box.bottom>innerHeight*.45);
  if(manualScene||motionPaused)return;
  const panel=$('.explode-sticky'),pinned=getComputedStyle(panel).position==='sticky';
  if(pinned){const header=$('.site-header').offsetHeight;seek((header-box.top)/Math.max(1,section.offsetHeight-panel.offsetHeight)*100);}
  else{seek((innerHeight*.88-box.top)/Math.max(1,innerHeight*.6)*100);}
 };
 if(motionPaused)seek(100);else if(manualScene)seek(previous);else scene.updateFromScroll();
}
