function setupForms(){$$('.brief-form').forEach(form=>{form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=[...new FormData(form).entries()].filter(([,v])=>String(v).trim());const text='FORKLS — '+form.dataset.brief+'\n\n'+data.map(([k,v])=>k+': '+String(v).trim()).join('\n\n')+'\n\nPrepared locally. This brief has not been sent. Configuration, availability and suitability require confirmation by FORKLS.';const result=form.nextElementSibling;result.hidden=false;result.innerHTML='<h3>Your brief is ready.</h3><p class="note">Nothing has been sent. Download this brief and share it through the official FORKLS contact page.</p><pre></pre><div class="actions"><a class="pill download-brief" download>Download brief</a><a class="pill plain" href="https://forkls.com/contact" target="_blank" rel="noopener">Open official contact page</a></div>';$('pre',result).textContent=text;const download=$('.download-brief',result);download.href='data:text/plain;charset=utf-8,'+encodeURIComponent(text);download.download='forkls-'+form.dataset.brief.toLowerCase().replace(/\s+/g,'-')+'.txt';result.scrollIntoView({behavior:motionPaused?'instant':'smooth',block:'center'});});});}
