function toggleChat(open){const panel=$('#finn-chat');panel.hidden=!open;$('.bot-launch').setAttribute('aria-expanded',String(open));if(open)$('.chat-input input').focus();else $('.bot-launch').focus();}
function chatAsk(value){const text=value.trim();if(!text)return;const log=$('.chat-log'),msg=document.createElement('div');msg.className='bubble user';msg.textContent=text;log.append(msg);const match=chatKnowledge.find(x=>x.keys.test(text))||{text:'I can help with FORKLS motors, drone missions, parts, support and company information. For a specific engineering answer, the team will need your requirements.',links:[['Prepare a question for the team','/contact']]};const reply=document.createElement('div');reply.className='bubble';reply.textContent=match.text;match.links.forEach(([t,p])=>{const a=document.createElement('a');a.href='#'+p;a.textContent=t;reply.append(a)});log.append(reply);log.scrollTop=log.scrollHeight;}
